import React from "react";
import {
  FaUser,
  FaPhone,
  FaMapPin,
  FaImage,
  FaTag,
  FaHireAHelper,
  FaClock,
  FaLink,
  FaChevronDown,
} from "react-icons/fa";

// استایل فیلدها
const fieldWrapClass =
  "relative flex items-center w-full h-[58px] rounded-2xl border border-gray-200 bg-white px-4 gap-3 shadow-sm transition-all duration-200 focus-within:border-blue-400 focus-within:ring-4 focus-within:ring-blue-500/10";

const inputClass =
  "flex-1 min-w-0 h-full bg-transparent text-right text-[15px] text-gray-800 placeholder:text-gray-400 outline-none";

const selectClass =
  "flex-1 min-w-0 h-full bg-transparent text-right text-[15px] text-gray-800 outline-none appearance-none cursor-pointer";

const iconClass =
  "shrink-0 w-[19px] h-[19px] text-gray-400";

class CustomerRequestForm extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      fullName: "",
      mobile: "",
      landline: "",
      province: "",
      address: "",
      deviceType: "",
      deviceBrand: "",
      deviceIssue: "",
      visitTime: "",
      description: "",
    };

    this.handleChange = this.handleChange.bind(this);
    this.handleSubmit = this.handleSubmit.bind(this);
  }

  handleChange(field) {
    return (e) => {
      this.setState({
        [field]: e.target.value,
      });
    };
  }

  handleSubmit(e) {
    e.preventDefault();

    // منطق ثبت درخواست
    console.log(this.state);
  }

  render() {
    const {
      fullName,
      mobile,
      landline,
      province,
      address,
      deviceType,
      deviceBrand,
      deviceIssue,
      visitTime,
      description,
    } = this.state;

    return (
      <div
        dir="rtl"
        lang="fa"
        className="min-h-screen bg-[#f6f7fb] px-4 py-6"
      >
        <div className="w-full max-w-md mx-auto">

          {/* هدر */}
          <div className="mb-7 text-center">
            <div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-2xl bg-blue-600 shadow-lg shadow-blue-600/20">
              <FaUser className="text-xl text-white" />
            </div>

            <h1 className="text-[20px] font-bold text-gray-900">
              ثبت درخواست مشتری
            </h1>

            <p className="mt-2 text-[13px] leading-6 text-gray-500">
              اطلاعات مشتری و دستگاه را با دقت وارد کنید
            </p>
          </div>

          {/* فرم */}
          <form
            onSubmit={this.handleSubmit}
            className="flex flex-col gap-3.5"
          >

            {/* نام کامل */}
            <div className={fieldWrapClass}>
              <FaUser className={iconClass} />

              <input
                type="text"
                placeholder="نام کامل"
                value={fullName}
                onChange={this.handleChange("fullName")}
                className={inputClass}
              />
            </div>

            {/* شماره موبایل */}
            <div className={fieldWrapClass}>
              <FaPhone className={iconClass} />

              <input
                type="tel"
                inputMode="numeric"
                placeholder="شماره موبایل"
                value={mobile}
                onChange={this.handleChange("mobile")}
                className={inputClass}
              />
            </div>

            {/* تلفن ثابت */}
            <div className={fieldWrapClass}>
              <FaPhone className={iconClass} />

              <input
                type="tel"
                inputMode="numeric"
                placeholder="تلفن ثابت"
                value={landline}
                onChange={this.handleChange("landline")}
                className={inputClass}
              />
            </div>

            {/* استان */}
            <div className={fieldWrapClass}>
              <FaMapPin className={iconClass} />
              <select
                value={province}
                onChange={this.handleChange("province")}
                className={selectClass}
              >
                <option value="" disabled>
                  استان
                </option>

                <option value="tehran">تهران</option>
                <option value="isfahan">اصفهان</option>
                <option value="fars">فارس</option>
                <option value="khorasan-razavi">
                  خراسان رضوی
                </option>
                <option value="alborz">البرز</option>
              </select>

              <FaChevronDown className="w-3.5 h-3.5 text-gray-400" />
            </div>

            {/* آدرس */}
            <div className={fieldWrapClass}>
              <FaMapPin className={iconClass} />

              <input
                type="text"
                placeholder="آدرس"
                value={address}
                onChange={this.handleChange("address")}
                className={inputClass}
              />
            </div>

            {/* نوع دستگاه */}
            <div className={fieldWrapClass}>
              <FaImage className={iconClass} />

              <select
                value={deviceType}
                onChange={this.handleChange("deviceType")}
                className={selectClass}
              >
                <option value="" disabled>
                  نوع دستگاه
                </option>

                <option value="washer">
                  ماشین لباسشویی
                </option>

                <option value="fridge">
                  یخچال
                </option>

                <option value="ac">
                  کولر گازی
                </option>

                <option value="tv">
                  تلویزیون
                </option>
              </select>

              <FaChevronDown className="w-3.5 h-3.5 text-gray-400" />
            </div>

            {/* برند دستگاه */}
            <div className={fieldWrapClass}>
              <FaTag className={iconClass} />

              <select
                value={deviceBrand}
                onChange={this.handleChange("deviceBrand")}
                className={selectClass}
              >
                <option value="" disabled>
                  برند دستگاه
                </option>

                <option value="samsung">
                  سامسونگ
                </option>

                <option value="lg">
                  ال‌جی
                </option>

                <option value="snowa">
                  اسنوا
                </option>

                <option value="pakshoma">
                  پاکشوما
                </option>
              </select>

              <FaChevronDown className="w-3.5 h-3.5 text-gray-400" />
            </div>

            {/* ایراد دستگاه */}
            <div className={fieldWrapClass}>
              <FaHireAHelper className={iconClass} />

              <input
                type="text"
                placeholder="ایراد دستگاه"
                value={deviceIssue}
                onChange={this.handleChange("deviceIssue")}
                className={inputClass}
              />
            </div>

            {/* زمان مراجعه */}
            <div className={fieldWrapClass}>
              <FaClock className={iconClass} />

              <input
                type="text"
                placeholder="زمان مراجعه"
                value={visitTime}
                onChange={this.handleChange("visitTime")}
                className={inputClass}
              />
            </div>

            {/* توضیحات */}
            <div className={fieldWrapClass}>
              <FaLink className={iconClass} />

              <input
                type="text"
                placeholder="توضیحات"
                value={description}
                onChange={this.handleChange("description")}
                className={inputClass}
              />
            </div>
            {/* دکمه ثبت */}
            <button
              type="submit"
              className="mt-2 h-[58px] w-full rounded-2xl bg-blue-600 text-[15px] font-bold text-white shadow-lg shadow-blue-600/20 transition-all duration-200 active:scale-[0.98] active:bg-blue-700"
            >
              ثبت درخواست
            </button>

          </form>
        </div>
      </div>
    );
  }
}

export default CustomerRequestForm;
